def transform(grid):
    g = np.array(grid)
    out = g.copy()
    H, W = g.shape
    frame = int(g[0, 0])
    bg = background(g)
    objs = [o for o in objects(g, bg=bg) if o["colour"] != frame]
    dirs = [(-1, 0), (1, 0), (0, -1), (0, 1)]
    for o in objs:
        cells = set(o["cells"])
        c = int(o["colour"])
        centre = None
        for (y, x) in cells:
            if all((y + dy, x + dx) in cells for dy, dx in dirs):
                centre = (y, x)
                break
        if centre is None:
            continue
        cy, cx = centre
        best, bestlen = None, -1
        for dy, dx in dirs:
            n = 0
            while (cy + dy * (n + 1), cx + dx * (n + 1)) in cells:
                n += 1
            if n > bestlen:
                best, bestlen = (dy, dx), n
        dy, dx = best

        def edge(dy, dx):
            if dy == -1: return (0, cx)
            if dy == 1: return (H - 1, cx)
            if dx == -1: return (cy, 0)
            return (cy, W - 1)

        ly, lx = edge(dy, dx)
        oy, ox = edge(-dy, -dx)
        out[ly, lx] = 0
        out[oy, ox] = c
        emit(out, f"Cross of colour {c} (centre {centre}) has its long arm pointing {best}; "
                  f"mark 0 on the frame at {(ly, lx)} and colour {c} on the opposite frame cell {(oy, ox)}.")
    emit(out, "All crosses have marked the frame: final output.")
    return out
